#include <algorithm>
#include <fstream>
#include <functional>
#include <limits>
#include <numeric>
#include <utility>
#include <vector>
struct Point { int x, y; };
int main() {
    std::ifstream in("reduce.in");
    std::ofstream out("reduce.out");
    int n;
    in >> n;
    std::vector<Point> p(n);
    for (auto& point : p) in >> point.x >> point.y;
    std::vector<int> byX(n), byY(n);
    std::iota(byX.begin(), byX.end(), 0);
    std::iota(byY.begin(), byY.end(), 0);
    std::sort(byX.begin(), byX.end(), [&](int a, int b) { return std::pair<int,int>{p[a].x,a} < std::pair<int,int>{p[b].x,b}; });
    std::sort(byY.begin(), byY.end(), [&](int a, int b) { return std::pair<int,int>{p[a].y,a} < std::pair<int,int>{p[b].y,b}; });
    std::vector<bool> removed(n, false);
    long long best = std::numeric_limits<long long>::max();
    std::function<void(int)> search = [&](int left) {
        int lx = 0, rx = n - 1, ly = 0, ry = n - 1;
        while (removed[byX[lx]]) ++lx;
        while (removed[byX[rx]]) --rx;
        while (removed[byY[ly]]) ++ly;
        while (removed[byY[ry]]) --ry;
        long long area = 1LL * (p[byX[rx]].x - p[byX[lx]].x) * (p[byY[ry]].y - p[byY[ly]].y);
        best = std::min(best, area);
        if (left == 0) return;
        std::vector<int> candidates{byX[lx], byX[rx], byY[ly], byY[ry]};
        std::sort(candidates.begin(), candidates.end());
        candidates.erase(std::unique(candidates.begin(), candidates.end()), candidates.end());
        for (int id : candidates) {
            removed[id] = true;
            search(left - 1);
            removed[id] = false;
        }
    };
    search(3);
    out << best << '\n';
}
