#include <algorithm>
#include <fstream>
#include <vector>
int main() {
    std::ifstream in("diamond.in");
    std::ofstream out("diamond.out");
    int n;
    long long k;
    in >> n >> k;
    std::vector<long long> size(n);
    for (auto& s : size) in >> s;
    std::sort(size.begin(), size.end());
    std::vector<int> end(n), length(n), suffix(n + 1, 0);
    int right = 0;
    for (int left = 0; left < n; ++left) {
        while (right < n && size[right] - size[left] <= k) ++right;
        end[left] = right;
        length[left] = right - left;
    }
    for (int i = n - 1; i >= 0; --i) suffix[i] = std::max(length[i], suffix[i + 1]);
    int best = 0;
    for (int i = 0; i < n; ++i) best = std::max(best, length[i] + suffix[end[i]]);
    out << best << '\n';
}
