#include <fstream>
#include <numeric>
#include <vector>
class DSU {
    std::vector<int> parent, size;
public:
    explicit DSU(int n) : parent(n), size(n, 1) { std::iota(parent.begin(), parent.end(), 0); }
    int find(int a) {
        while (parent[a] != a) { parent[a] = parent[parent[a]]; a = parent[a]; }
        return a;
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (size[a] < size[b]) { int t = a; a = b; b = t; }
        parent[b] = a; size[a] += size[b];
        return true;
    }
};
int main() {
    std::ifstream in("closing.in");
    std::ofstream out("closing.out");
    int n, m;
    in >> n >> m;
    std::vector<std::vector<int>> adjacency(n);
    for (int i = 0; i < m; ++i) {
        int a, b; in >> a >> b; --a; --b;
        adjacency[a].push_back(b); adjacency[b].push_back(a);
    }
    std::vector<int> order(n);
    for (int& v : order) { in >> v; --v; }
    DSU dsu(n);
    std::vector<bool> active(n, false), answer(n, false);
    int components = 0;
    for (int i = n - 1; i >= 0; --i) {
        int v = order[i]; active[v] = true; ++components;
        for (int u : adjacency[v]) if (active[u] && dsu.unite(v, u)) --components;
        answer[i] = components == 1;
    }
    for (bool connected : answer) out << (connected ? "YES" : "NO") << '\n';
}
